      this.sweepFloatingDecor();
      this.sweepPockets(60);
      this.sealLiquids();
      this.decorateWater(rng);
      this.decoratePonds(rng);
      this.fillMossCorners();
      this.springFalls();
      this.faults = (this.faults || []).filter((f) => this.get(f.x, f.y) === T.FAULTSTONE);
      this.placeRichOres();
      this.spawnX = vx0 + vx1 >> 1;
      this.spawnY = vh - 3;
