        const tx = Math.floor((o.x + o.w / 2) / TS);
        const ty = Math.round((o.y + o.h) / TS);
        o.w = s.w;
        o.h = s.h;
        o.x = tx * TS + Math.round((TS - s.w) / 2);
        o.y = ty * TS - s.h;
