          const g = c.createRadialGradient(cx, sy + TS - 5, 0, cx, sy + TS - 5, 11);
          g.addColorStop(0, "#ffb050");
          g.addColorStop(1, "rgba(255,90,20,0)");
          c.fillStyle = g;
          c.fillRect(sx - 2, sy + 4, TS + 4, TS);
          c.globalCompositeOperation = "source-over";
