      c.globalAlpha = 0.55;
      c.strokeRect(x + 0.5, y + 0.5, Wd - 1, 29);
      c.globalAlpha = 1;
      const beat = Math.pow(Math.max(0, Math.sin(t * (2.2 + st * 1.6))), 6);
      const hr = 6 + beat * 2.2;
